  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Docetaxel in humans has a reported oral bioavailability of about 8%, which is below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Danoprevir 100 mg without ritonavir has an absolute oral bioavailability of 1.15% in healthy subjects, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Fluticasone has negligible (<1%) bioavailability via gastrointestinal absorption in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human records report absolute oral bioavailability values well below 20% (8%, 1.15%, <1%), consistently supporting a low F prediction.",
  "evidence_gaps": [
    "Molecule 4 provides only qualitative bioavailability over 6 hours without a threshold-relevant F value, so it is not informative for the F >= 20% decision.",
    "Some records use unspecified bioavailability report types, but the numeric human low-bioavailability values are consistent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

